library(testthat)

val_strip_html <- function(x) {
  if (is.null(x) || length(x) == 0) return("")
  txt <- paste(as.character(x), collapse = " ")
  txt <- gsub("<[^>]*>", " ", txt)
  txt <- gsub("&amp;", "&", txt, fixed = TRUE)
  txt <- gsub("&lt;", "<", txt, fixed = TRUE)
  txt <- gsub("&gt;", ">", txt, fixed = TRUE)
  gsub("[[:space:]]+", " ", trimws(txt))
}

val_extract <- function(txt, pattern, group = 1L) {
  m <- regexec(pattern, txt, perl = TRUE)
  hits <- regmatches(txt, m)[[1]]
  if (length(hits) <= group) return(NA_character_)
  trimws(hits[group + 1L])
}

val_parse_stats <- function(res) {
  txt <- val_strip_html(res$networkStats$content)
  hb_none <- grepl("Highest Betweenness:\\s*none", txt, perl = TRUE)
  list(
    txt = txt,
    n_nodes = suppressWarnings(as.integer(val_extract(txt, "Number of Nodes:\\s*([0-9]+)"))),
    n_edges = suppressWarnings(as.integer(val_extract(txt, "Number of Edges:\\s*([0-9]+)"))),
    density = suppressWarnings(as.numeric(val_extract(txt, "Network Density:\\s*([0-9.eE+-]+)"))),
    density_adj = val_extract(txt, "Network Density:\\s*[0-9.eE+-]+\\s*\\(([^)]+)\\s+connected\\)"),
    is_connected = identical(val_extract(txt, "Is Connected:\\s*(Yes|No)"), "Yes"),
    hd_node = val_extract(txt, "Highest Degree:\\s*(.*?)\\s*\\(\\s*[0-9.eE+-]+\\s+[^)]+\\)"),
    hd_val  = suppressWarnings(as.numeric(val_extract(txt, "Highest Degree:\\s*.*?\\(\\s*([0-9.eE+-]+)\\s+[^)]+\\)"))),
    hb_node = if (hb_none) "none" else val_extract(txt, "Highest Betweenness:\\s*(.*?)\\s*\\(\\s*[0-9.eE+-]+\\s*\\)"),
    hb_val  = if (hb_none) 0 else suppressWarnings(as.numeric(val_extract(txt, "Highest Betweenness:\\s*.*?\\(\\s*([0-9.eE+-]+)\\s*\\)")))
  )
}

val_notices <- function(res) {
  paste(as.character(res$notices$content), collapse = "\n")
}

