test_that("C01/C02/C03/C05/C08: tiny 5-node graph matches exact hand calculation and sna", {
  # Oracle: exact hand calculation + sna::gden, sna::degree, sna::betweenness (v2.8)
  skip_if_not_installed("sna")
  d <- data.frame(
    from = factor(c("A", "A", "B", "B", "C")),
    to   = factor(c("B", "E", "E", "C", "D"))
  )
  res <- jjarcdiagram(data = d, source = "from", target = "to", showStats = TRUE, showSummary = TRUE)
  st  <- val_parse_stats(res)

  nodes <- c("A", "B", "C", "D", "E")
  mat <- matrix(0, 5, 5, dimnames = list(nodes, nodes))
  for (i in seq_len(nrow(d))) {
    mat[as.character(d$from[i]), as.character(d$to[i])] <- 1
    mat[as.character(d$to[i]), as.character(d$from[i])] <- 1
  }

  expect_equal(st$n_nodes, 5L)
  expect_equal(st$n_edges, 5L)
  expect_equal(st$density, sna::gden(mat, mode = "graph"), tolerance = 1e-4)
  expect_true(st$is_connected)
  expect_equal(st$hd_node, "B")
  expect_equal(st$hd_val, max(sna::degree(mat, gmode = "graph", cmode = "freeman")), tolerance = 1e-8)
  expect_equal(st$hb_node, "B")
  expect_equal(st$hb_val, max(sna::betweenness(mat, gmode = "graph", cmode = "undirected")), tolerance = 1e-8)
})

