  st  <- val_parse_stats(res)

  expect_equal(st$n_nodes, 9L)
  expect_equal(st$n_edges, 12L)
  expect_equal(st$density, round(1/3, 4), tolerance = 1e-4)
  expect_equal(st$hd_node, "H")
  expect_equal(st$hd_val, 4, tolerance = 1e-8)
  expect_equal(st$hb_node, "M")
  expect_equal(st$hb_val, 16, tolerance = 1e-8)
  expect_match(st$txt, "Bridge Entity:.*'M' has the highest betweenness")
})

