  st_str <- val_parse_stats(jjarcdiagram(data = d, source = "from", target = "to", weight = "w",
                                         weightMode = "strength", showStats = TRUE))
  st_dst <- val_parse_stats(jjarcdiagram(data = d, source = "from", target = "to", weight = "w",
                                         weightMode = "distance", showStats = TRUE))
