test_that("C06/C09/C10: metamorphic positive weight rescaling (10x) scales strength 10x and preserves betweenness", {
  # Oracle: scale-invariance property of shortest-path betweenness under w -> k*w (k > 0)
  d1 <- data.frame(
    from = factor(c("A","A","B","B","C","D")),
    to   = factor(c("B","E","E","C","D","F")),
    w    = c(4, 2, 3, 5, 1, 2)
  )
  d10 <- d1; d10$w <- d1$w * 10
  s1  <- val_parse_stats(jjarcdiagram(data = d1,  source = "from", target = "to", weight = "w", weightMode = "strength", showStats = TRUE))
  s10 <- val_parse_stats(jjarcdiagram(data = d10, source = "from", target = "to", weight = "w", weightMode = "strength", showStats = TRUE))
  expect_equal(s10$hd_val, s1$hd_val * 10, tolerance = 1e-6)
  expect_equal(s10$hb_val, s1$hb_val, tolerance = 1e-6)
})

