test_that("C17/C18: density interpretation and size/density guard thresholds fire at exact boundaries", {
  # Oracle: exact density = 2m/(n(n-1)) and stated guard inequalities (<3, <5, <10, >0.7, <0.05 & n>20)
  make_path <- function(n) data.frame(from = factor(paste0("N", seq_len(n - 1L))), to = factor(paste0("N", seq.int(2L, n))))
  expect_match(val_notices(jjarcdiagram(data = make_path(2), source = "from", target = "to")), "Trivial Network")
  expect_match(val_notices(jjarcdiagram(data = make_path(4), source = "from", target = "to")), "Very Small Network")
  expect_match(val_notices(jjarcdiagram(data = make_path(9), source = "from", target = "to")), "Small Network")
  expect_false(grepl("Small Network", val_notices(jjarcdiagram(data = make_path(10), source = "from", target = "to")), fixed = TRUE))

  # n=10 path: D = 9/45 = 0.20 exact -> 'sparsely' (strict > 0.2)
  st_02 <- val_parse_stats(jjarcdiagram(data = make_path(10), source = "from", target = "to", showStats = TRUE))
  expect_equal(st_02$density_adj, "sparsely")

  # Sparse INFO guard: n=21 directed path -> D = 20/420 = 0.0476 < 0.05 -> fires; n=21 cycle -> D = 0.05 exact -> silent
  expect_match(val_notices(jjarcdiagram(data = make_path(21), source = "from", target = "to", directed = TRUE)), "Sparse Network")
  cyc21 <- rbind(make_path(21), data.frame(from = factor("N21"), to = factor("N1")))
  expect_false(grepl("Sparse Network", val_notices(jjarcdiagram(data = cyc21, source = "from", target = "to", directed = TRUE)), fixed = TRUE))
})

