test_that("C23/C26/C30: bundled gene network renders PNG, obeys visibility toggles, and is deterministic", {
  # Oracle: deterministic parity + non-empty PNG rendering via public wrapper
  r1 <- jjarcdiagram(data = ClinicoPath::jjarcdiagram_gene_network, source = "source", target = "target",
                     weight = "weight", group = "pathway", directed = TRUE, showStats = TRUE, showSummary = TRUE)
  r2 <- jjarcdiagram(data = ClinicoPath::jjarcdiagram_gene_network, source = "source", target = "target",
                     weight = "weight", group = "pathway", directed = TRUE, showStats = TRUE, showSummary = TRUE)
  expect_identical(r1$networkStats$content, r2$networkStats$content)
  expect_identical(r1$reportSentence$content, r2$reportSentence$content)

  tf <- tempfile(fileext = ".png")
  on.exit(unlink(tf), add = TRUE)
  r1$plot$saveAs(tf)
  expect_true(file.exists(tf) && file.info(tf)$size > 1000)

  r_off <- jjarcdiagram(data = ClinicoPath::jjarcdiagram_gene_network, source = "source", target = "target",
                        showStats = FALSE, showSummary = FALSE, showAssumptions = FALSE, showGlossary = FALSE)
  expect_false(r_off$networkStats$visible)
  expect_false(r_off$reportSentence$visible)
  expect_false(r_off$assumptions$visible)
  expect_false(r_off$glossary$visible)
})

