  res <- jjarcdiagram(data = ClinicoPath::jjarcdiagram_disease_network,
                      source = "source", target = "target", group = "category",
                      colorByGroup = FALSE, analysisPreset = "custom", showSummary = TRUE)
  sm <- val_strip_html(res$reportSentence$content)
  expect_false(grepl("a network network", sm, fixed = TRUE))
  expect_false(grepl("color-coding", sm, fixed = TRUE))
})

test_that("C19/C24 [VAL-jjarcdiagram-13/14]: sortNodes='none' preserves order under aggregation and presets respect explicit sortNodes", {
  # Oracle: first-appearance sequence preservation and non-clobbering preset behavior
  Class   <- getFromNamespace("jjarcdiagramClass", "ClinicoPath")
  Options <- getFromNamespace("jjarcdiagramOptions", "ClinicoPath")
  d <- data.frame(from = factor(c("Zebra","Mango","Apple")), to = factor(c("Mango","Apple","Beta")))
  a1 <- Class$new(options = Options$new(source = "from", target = "to", aggregateEdges = TRUE, sortNodes = "none"), data = d)
  a1$run()
  p1 <- a1$.__enclos_env__$private
  nd1 <- p1$.prepareNetworkData()
  expect_identical(nd1$vlabels_display[p1$.calculateNodeOrdering(nd1)], c("Zebra", "Mango", "Apple", "Beta"))

  a2 <- Class$new(options = Options$new(source = "from", target = "to", analysisPreset = "pathway_network", sortNodes = "name"), data = d)
  a2$run()
  expect_identical(a2$.__enclos_env__$private$.option("sortNodes"), "name")
})

test_that("C12 [method-choice]: duplicate edges in Distance mode aggregate by minimum distance", {
  # Oracle: shortest parallel link between A and B among distances (2, 10) is min(2, 10) = 2
  d <- data.frame(from = factor(c("A","A","B")), to = factor(c("B","B","C")), w = c(2, 10, 5))
  res <- jjarcdiagram(data = d, source = "from", target = "to", weight = "w",
                      weightMode = "distance", aggregateEdges = TRUE, showStats = TRUE)
  st <- val_parse_stats(res)
  expect_equal(st$n_edges, 2L)
  expect_equal(st$hd_node, "B")
  expect_equal(st$hd_val, 7, tolerance = 1e-8)
  expect_match(val_notices(res), "minimum distance")
})

test_that("AUD-jjarcdiagram-01: Valid -> Invalid -> Valid R6 lifecycle clears stale outputs on error", {
  # Oracle: jamovi R6 reuse contract (no stale completed output beside an ERROR notice)
  Class <- getFromNamespace("jjarcdiagramClass", "ClinicoPath")
  Opts  <- getFromNamespace("jjarcdiagramOptions", "ClinicoPath")
  d <- data.frame(from = factor(c("A","B","C")), to = factor(c("B","C","D")), w = c(1, 0, 2))
  a <- Class$new(Opts$new(source = "from", target = "to", weight = "w",
                          weightMode = "strength", showStats = TRUE, showSummary = TRUE), d)
  a$run()
  expect_match(val_strip_html(a$results$todo$content), "Network Analysis Complete")

  a$.__enclos_env__$private$.options <- Opts$new(source = "from", target = "to", weight = "w",
                                                 weightMode = "distance", showStats = TRUE, showSummary = TRUE)
  a$run()
  expect_match(val_notices(a$results), "Zero Edge Distances")
  expect_identical(val_strip_html(a$results$todo$content), "")
  expect_identical(val_strip_html(a$results$networkStats$content), "")
  expect_identical(val_strip_html(a$results$reportSentence$content), "")
})

test_that("AUD-jjarcdiagram-02: mixed 12-order dynamic-range weights preserve exact betweenness", {
  # Oracle: exact IEEE-754 Brandes/Dijkstra on S-M(1e6), M-T(1e6), S-C(1e-6), C-T(1e-6), C-Z(1e-6): C = 3.0
  d <- data.frame(
    from = factor(c("S","M","S","C","C")),
    to   = factor(c("M","T","C","T","Z")),
    w    = c(1e6, 1e6, 1e-6, 1e-6, 1e-6)
  )
  st <- val_parse_stats(jjarcdiagram(data = d, source = "from", target = "to", weight = "w",
                                     weightMode = "strength", showStats = TRUE))
  expect_equal(st$hb_node, "C")
  expect_equal(st$hb_val, 3, tolerance = 1e-6)
})

test_that("AUD-jjarcdiagram-03: blank and whitespace-only node labels are excluded cleanly without crashing", {
  # Oracle: only row 1 (A-B) has non-blank endpoints -> 2 nodes, 1 edge
  d <- data.frame(from = factor(c("A", "", "   ")), to = factor(c("B", "B", "C")))
  expect_no_error(res <- jjarcdiagram(data = d, source = "from", target = "to", showStats = TRUE))
  st <- val_parse_stats(res)
  expect_equal(st$n_nodes, 2L)
  expect_equal(st$n_edges, 1L)
  expect_match(val_notices(res), "Rows Excluded")
})

test_that("AUD-jjarcdiagram-04: optional group column with NAs preserves all edges and network topology", {
  # Oracle: adding optional coloring metadata with missing labels must not delete valid edges
  d <- data.frame(
    from = factor(c("A","B","C","D","A")),
    to   = factor(c("B","C","D","E","E")),
    w    = c(1, 2, 3, 4, 5),
    grp  = factor(c("G1", "G1", NA, NA, "G2"))
  )
  st_no  <- val_parse_stats(jjarcdiagram(data = d, source = "from", target = "to", weight = "w", showStats = TRUE))
  res_gr <- jjarcdiagram(data = d, source = "from", target = "to", weight = "w", group = "grp", showStats = TRUE)
  st_gr  <- val_parse_stats(res_gr)
  expect_equal(st_gr$n_edges, st_no$n_edges)
  expect_equal(st_gr$density, st_no$density, tolerance = 1e-8)
  expect_match(val_notices(res_gr), "Missing Group Labels")
})

test_that("REV-jjarcdiagram-01: directed = TRUE renders subtitle visibly inside bottom margin", {
  # Oracle: rendered PNG bytes must differ between directed = FALSE and directed = TRUE
  # when edge geometry is identical, proving the directed subtitle is not clipped off-canvas.
  Class <- getFromNamespace("jjarcdiagramClass", "ClinicoPath")
  Opts  <- getFromNamespace("jjarcdiagramOptions", "ClinicoPath")
  d <- data.frame(from = factor(c("A", "B", "C")), to = factor(c("B", "C", "D")))

  render_md5 <- function(dir_flag) {
    a <- Class$new(Opts$new(source = "from", target = "to", directed = dir_flag), d)
    a$run()
    tf <- tempfile(fileext = ".png")
    on.exit(unlink(tf), add = TRUE)
    grDevices::png(tf, width = a$results$plot$width, height = a$results$plot$height)
    ret <- a$.__enclos_env__$private$.plot(a$results$plot, NULL, NULL)
    grDevices::dev.off()
    expect_true(isTRUE(ret))
    unname(tools::md5sum(tf))
  }

  expect_false(identical(render_md5(FALSE), render_md5(TRUE)))
})

test_that("REV-jjarcdiagram-02: notices sort by severity priority (ERROR above INFO)", {
  # Oracle: ERROR must precede INFO even when analysisPreset emits an INFO notice first.
  d <- data.frame(from = factor(c("A", "B")), to = factor(c("B", "C")), w = c(-1, 2))
  res <- jjarcdiagram(data = d, source = "from", target = "to", weight = "w",
                      analysisPreset = "patient_network")
  txt <- as.character(res$notices$content)
  err_pos  <- regexpr("ERROR: Negative Edge Weights", txt, fixed = TRUE)
  info_pos <- regexpr("Analysis Preset Active", txt, fixed = TRUE)
  expect_gt(err_pos, 0L)
  expect_gt(info_pos, 0L)
  expect_lt(err_pos, info_pos)
})

