test_that("REV-jjarcdiagram-04: pure data-route plot does not bloat state and returns FALSE on invalid data", {
  Class <- getFromNamespace("jjarcdiagramClass", "ClinicoPath")
  Opts  <- getFromNamespace("jjarcdiagramOptions", "ClinicoPath")
  d_ok <- data.frame(from = factor(c("A", "B")), to = factor(c("B", "C")), w = c(1, 2))
