  expect_false(isTRUE(a_bad$.__enclos_env__$private$.plot(a_bad$results$plot, NULL, NULL)))
})

test_that("SEC-jjarcdiagram-01: .sourcifyOption() blocks syntax-pane argument injection across all shapes", {
  # Oracle: parsed asSource() must bind no injected args, contain no call AST nodes in values,
  # and round-trip escaped character scalars verbatim without evaluating payloads.
  Class <- getFromNamespace("jjarcdiagramClass", "ClinicoPath")
  Opts  <- getFromNamespace("jjarcdiagramOptions", "ClinicoPath")
  d <- data.frame(src = factor(c("A", "B")), tgt = factor(c("B", "C")))

  check_no_injection <- function(an, opt_name = NULL, expected_val = NULL) {
    src <- an$asSource()
    ex <- parse(text = src)[[1]]
    expect_true(is.call(ex))
    mc <- match.call(ClinicoPath::jjarcdiagram, ex)
    expect_true(is.call(mc))
    arg_list <- as.list(ex)[-1]
    expect_false(any(c("showNodes", "horizontal", "directed") %in% names(arg_list)))
    for (v in arg_list) {
      expect_false(is.call(v))
    }
    if (!is.null(opt_name) && !is.null(expected_val)) {
      expect_identical(arg_list[[opt_name]], expected_val)
    }
  }

  # 1. Free-text OptionString quote-break, trailing backslash, and newline
  for (payload in c(
    'ok", showNodes = {stop("CANARY"); TRUE}, horizontal = "FALSE',
    "trailing_backslash\\",
    "line1\nline2"
  )) {
    an <- Class$new(Opts$new(source = "src", target = "tgt"), d)
    o <- an$options$option("plotTitle")
    o$value <- payload
    check_no_injection(an, "plotTitle", payload)
  }

  # 2. Non-String OptionList mutated to quote-breaking string (.omv fromProtoBuf path)
  an_list <- Class$new(Opts$new(source = "src", target = "tgt"), d)
  o_ns <- an_list$options$option("nodeSize")
  p_ns <- 'degree", showNodes = {stop("CANARY"); TRUE}, arcWidth = "fixed'
  o_ns$value <- p_ns
  check_no_injection(an_list, "nodeSize", p_ns)

  # 3. Undeclared option name added to Options (.omv fromProtoBuf path)
  an_undec <- Class$new(Opts$new(source = "src", target = "tgt"), d)
  an_undec$options$.addOption(
    jmvcore:::Option$new('showNodes = TRUE, horizontal = {stop("CANARY"); TRUE}, directed', FALSE)
  )
  check_no_injection(an_undec)

  # 4. List value and multi-element character vector injected on option
  an_lval <- Class$new(Opts$new(source = "src", target = "tgt"), d)
  o_l <- an_lval$options$option("plotTitle")
  o_l$value <- list('a", showNodes = {stop("CANARY"); TRUE}, b = "c')
  check_no_injection(an_lval)

  an_cvec <- Class$new(Opts$new(source = "src", target = "tgt"), d)
  o_cv <- an_cvec$options$option("plotTitle")
  o_cv$value <- c('a", showNodes = {stop("CANARY"); TRUE}, b = "c', "d")
  check_no_injection(an_cvec)
})

test_that("SEC-jjarcdiagram-02: .validateOptions() blocks out-of-range numeric and invalid enum values", {
  Class <- getFromNamespace("jjarcdiagramClass", "ClinicoPath")
  Opts  <- getFromNamespace("jjarcdiagramOptions", "ClinicoPath")
  d <- data.frame(src = factor(c("A", "B")), tgt = factor(c("B", "C")), w = c(1, 2))

  an_alpha <- Class$new(Opts$new(source = "src", target = "tgt", weight = "w"), d)
  o_a <- an_alpha$options$option("arcTransparency")
  o_a$value <- 2.5
  an_alpha$run(noThrow = TRUE)
  expect_match(val_notices(an_alpha$results), "ERROR: Invalid Option Value")
  expect_false(isTRUE(an_alpha$.__enclos_env__$private$.plot(an_alpha$results$plot, NULL, NULL)))

  an_mode <- Class$new(Opts$new(source = "src", target = "tgt", weight = "w"), d)
  o_m <- an_mode$options$option("weightMode")
  o_m$value <- "bogus"
  an_mode$run(noThrow = TRUE)
  expect_match(val_notices(an_mode$results), "ERROR: Invalid Option Value")
})

test_that("FIX-jjarcdiagram-01: .r.yaml clearWith covers all option-dependent result panels", {
  ry_path <- testthat::test_path("..", "..", "jamovi", "jjarcdiagram.r.yaml")
  skip_if_not(file.exists(ry_path), "source jamovi/jjarcdiagram.r.yaml not available")
  ry <- yaml::read_yaml(ry_path)
  by_name <- stats::setNames(ry$items, vapply(ry$items, `[[`, character(1), "name"))

  expect_true(all(c("plotTitle", "sortNodes", "weightMode", "analysisPreset") %in% by_name$notices$clearWith))
  expect_true(all(c("source", "target", "analysisPreset") %in% by_name$instructions$clearWith))
  expect_true("colorByGroup" %in% by_name$reportSentence$clearWith)
})
